// Every state of the module, as one value; a rule writes it in place, only after its guards held.
// state tasks: Map[TaskNo, Task]; state next_no: TaskNo = 1
struct World {
  std::map<model::TaskNo, model::Task> tasks;
  model::TaskNo next_no = model::TaskNo::proven(1);
  bool operator==(const World&) const = default;
};

// The errors the guards declare. A refused rule has changed nothing and sent nothing.
enum class Refusal : std::uint8_t { NoTask, AlreadyDone, NotDone };
[[nodiscard]] constexpr std::string_view name(Refusal e) noexcept {
  switch (e) {
    case Refusal::NoTask:
      return "NoTask";
    case Refusal::AlreadyDone:
      return "AlreadyDone";
    case Refusal::NotDone:
      return "NotDone";
  }
  std::unreachable();
}
// The lines out.line sends, collected; they leave only after commit.
using Lines = std::vector<std::string>;

// A call of rule add.
struct Add {
  model::Title title;
  model::Priority priority = model::Priority::Normal;
  std::set<model::Tag> tags = {};
};

// A call of rule list.
struct List {
  bool all = false;
  std::optional<model::Tag> tag = std::nullopt;
};

// A call of rule done.
struct Done {
  model::TaskNo no;
};

// A call of rule reopen.
struct Reopen {
  model::TaskNo no;
};

// A call of rule rename.
struct Rename {
  model::TaskNo no;
  model::Title title;
};

// A call of rule remove.
struct Remove {
  model::TaskNo no;
};

// A call of rule clear.
struct Clear {};

// A call of rule stats.
struct Stats {};

using Event = std::variant<Add, List, Done, Reopen, Rename, Remove, Clear, Stats>;
// Whether the event's rule writes the world: its @uses names a write.
[[nodiscard]] constexpr bool writes(const Event& e) noexcept {
  return !(std::holds_alternative<List>(e) || std::holds_alternative<Stats>(e));
}

// pub rule add(title: Title, priority: Priority = Normal, tags: Set[Tag] = Set()) -> TaskNo
[[nodiscard]] model::TaskNo add(World& w, Lines& out, model::Title title, model::Priority priority,
                                std::set<model::Tag> tags);

// pub rule list(all: Bool = false, tag: Option[Tag] = none)
// It only reads (no write in its @uses): the world is const.
void list(const World& w, Lines& out, bool all, std::optional<model::Tag> tag);

// @guard(no in tasks else NoTask, tasks[no].status == Open else AlreadyDone) pub rule done(no: TaskNo)
[[nodiscard]] std::expected<void, Refusal> done(World& w, Lines& out, model::TaskNo no);

// @guard(no in tasks else NoTask, tasks[no].status == Done else NotDone) pub rule reopen(no: TaskNo)
[[nodiscard]] std::expected<void, Refusal> reopen(World& w, Lines& out, model::TaskNo no);

