[[nodiscard]] std::expected<void, Refusal> remove(World& w, Lines& out, model::TaskNo no);

// pub rule clear() -> Int
[[nodiscard]] std::int64_t clear(World& w, Lines& out);

// The fields of Task that rule stats reads.
struct StatsTask {
  model::TaskNo no;
  model::Status status;
};
// The world as rule stats reads it: a store read builds this, not the whole world.
struct StatsWorld {
  rt::FlatMap<model::TaskNo, StatsTask> tasks;
  model::TaskNo next_no = model::TaskNo::proven(1);
};

// a count at a glance, without listing.
// pub rule stats()
// One body for World and StatsWorld.
template <class W>
void stats(const W& w, Lines& out) {
  const auto open = rt::length(w.tasks | std::views::values | std::views::filter([&](const auto& it) {
                                 return it.status == model::Status::Open;
                               }));
  out.push_back(rt::text::concat(open, " open, ", rt::length(w.tasks) - open, " done"));
}

// Runs the event's rule. Replies have no reader on a command line and stop here.
[[nodiscard]] std::expected<void, Refusal> apply(Event event, World& w, Lines& out);

